  <div className="lab-heading"><div><span>DEPLOYLAB PRACTICE ENVIRONMENT</span><h2>{title[mode]}</h2><p>Safe, deterministic simulations. No cloud accounts, credentials or real commands.</p></div><span className="lab-safe"><ShieldCheck size={14}/> SIMULATION ONLY</span></div>
  {mode==="troubleshoot"&&!deploymentTriggered&&<div className="obs-empty"><div className="obs-empty-icon"><Wrench size={25}/></div><span className="obs-kicker">DEPLOYMENT-AWARE TROUBLESHOOTING</span><h2>Start the selected deployment to open its incident lab</h2><p>Choose an architecture and start its deployment flow. DeployLab will then generate relevant incidents, diagnostics and recovery guidance from the selected provider, application and resources.</p><div className="obs-empty-steps"><span><CheckCircle2 size={14}/> Selected architecture</span><span><Activity size={14}/> Deployment context</span><span><Wrench size={14}/> Matching incidents</span></div><small>Simulation only · No live infrastructure is inspected</small></div>}{mode==="troubleshoot"&&deploymentTriggered&&<><div className="terraform-context"><div><span className="inspector-kicker">ACTIVE DEPLOYMENT · INCIDENT WORKSPACE</span><h3>{deploymentName}</h3><p>{deploymentProvider} · {deploymentResources.length} architecture components · {hasKubernetesCluster?"Kubernetes workload diagnostics":"Platform-specific diagnostics"}</p></div><span className="lab-safe"><CheckCircle2 size={14}/> CONTEXT LOADED</span></div><div className="lab-grid"><div className="lab-panel"><h3><Wrench size={16}/> Incident scenarios</h3>{activeFaults.map(f=><button key={f.id} className={fault.id===f.id?"lab-choice active":"lab-choice"} onClick={()=>{setFaultId(f.id);setRuntime(initialRuntime());setIncidentEvidence([]);setIncidentGuess("");setIncidentSolved(false);}}><b>{f.title}</b><small>{f.description}</small></button>)}</div><div className="lab-panel"><h3><TriangleAlert size={16}/> Incident investigation</h3><div className="incident-state"><b>{fault.title}</b><span>SIMULATED INCIDENT</span></div><p>{fault.description} Collect evidence from this deployment before choosing a likely cause.</p><div className="incident-symptom"><b>Observed symptom</b><p>{fault.symptom}</p></div><div className="incident-state"><b>{fault.component}</b><span>{fault.title.toUpperCase()}</span></div><p className="obs-muted">Affected architecture components: {deploymentResources.filter(r=>{const context=(fault.component+" "+fault.title).toLowerCase();return context.split(/[^a-z0-9]+/).filter(Boolean).some(term=>term.length>3&&(r.name+" "+r.kind+" "+(r.description||"")).toLowerCase().includes(term));}).map(r=>r.name).slice(0,3).join(", ")||deploymentResources.slice(-3).map(r=>r.name).join(", ")||deploymentName}</p><h4>Investigation tools</h4>{fault.evidenceCommands.map(cmd=><button key={cmd} className={incidentEvidence.includes(cmd)?"lab-choice active":"lab-choice"} onClick={()=>{setIncidentEvidence(e=>e.includes(cmd)?e:[...e,cmd]);setRuntime(s=>({...s,logs:[...s.logs,"$ "+cmd,"[SIM] Diagnostic evidence collected: "+cmd]}));}}><b>{cmd}</b><small>{incidentEvidence.includes(cmd)?"Evidence collected":"Collect diagnostic evidence"}</small></button>)}<div className="incident-state"><b>Evidence: {incidentEvidence.length}/4</b><span>{incidentEvidence.length>=2?"READY TO DIAGNOSE":"INVESTIGATING"}</span></div>{incidentEvidence.length>=2&&!incidentSolved&&<><h4>Choose the most likely cause</h4><select className="incident-select" value={incidentGuess} onChange={e=>setIncidentGuess(e.target.value)}><option value="">Select a diagnosis…</option>{fault.choices.map(x=><option key={x} value={x}>{x}</option>)}</select><button className="lab-primary" disabled={!incidentGuess} onClick={()=>{const correct=incidentGuess===fault.answer;setIncidentSolved(true);if(correct)setIncidentScore(s=>s+10);}}><CheckCircle2 size={14}/> Submit diagnosis</button></>}{incidentSolved&&<><h4>{incidentGuess===fault.answer?"Correct diagnosis":"Diagnosis reviewed"}</h4><p>{fault.diagnosis}</p><p>{fault.fix}</p><code>{fault.command}</code><button className="lab-primary" onClick={()=>setRuntime(s=>resolveFault(s,fault))}><CheckCircle2 size={14}/> Apply simulated recovery</button></>}<h4>Investigation log</h4><pre>{runtime.logs.join("\n")||"No commands run yet."}</pre><p>Challenge score: {incidentScore} points</p></div></div></>}
  {mode==="dashboard"&&<div className="deployment-module"><div className="module-heading"><div><span>DEPLOYMENT CONTROL PLANE</span><p>Follow application releases from infrastructure preparation through production health.</p></div><span className="simulation-badge">SIMULATION ENVIRONMENT</span></div><div className="module-stat-grid"><div className="module-stat"><small>AVAILABLE ARCHITECTURES</small><b>{architectureCount}</b><span>Deployment patterns</span></div><div className="module-stat"><small>SIMULATION STATUS</small><b>Ready</b><span>Safe, isolated scenarios</span></div><div className="module-stat"><small>DEPLOYMENT TARGETS</small><b>AWS · Azure · GCP</b><span>Cloud and Kubernetes</span></div><div className="module-stat"><small>OPERATING MODE</small><b>Simulated</b><span>No real resources created</span></div></div><div className="module-panel"><h3><Activity size={16}/> Deployment lifecycle</h3><div className="module-lifecycle">{["Infrastructure","Build & package","Security checks","Deploy workload","Verify release","Observe production"].map((x,i)=><div key={x}><span>{i+1}</span><b>{x}</b></div>)}</div></div><div className="module-panel"><h3><Layers size={16}/> Deployment workspace</h3><p>Choose a deployment architecture to inspect components and follow its release stages. The engineering modules provide simulated terminal commands, infrastructure planning, Kubernetes operations, security checks, cost estimates, runbooks and observability.</p></div></div>}
